import unittest
from main import run

class TestValidateCSVHeaders(unittest.TestCase):
    def test_missing_headers(self):
        input_data = {
            "file_path": "data.csv",
            "required_headers": ["name", "age", "email"]
        }
        expected_output = {
            "missing_headers": ["address"]
        }
        self.assertDictEqual(run(input_data), expected_output)

    def test_all_headers_present(self):
        input_data = {
            "file_path": "data.csv",
            "required_headers": ["name", "age", "email"]
        }
        expected_output = {
            "missing_headers": []
        }
        self.assertDictEqual(run(input_data), expected_output)

    def test_extra_headers(self):
        input_data = {
            "file_path": "data.csv",
            "required_headers": ["name", "age", "email", "address"]
        }
        expected_output = {
            "missing_headers": []
        }
        self.assertDictEqual(run(input_data), expected_output)

if __name__ == '__main__':
    unittest.main()
